import io.netty.buffer.Unpooled;
import org.junit.Assert;
import org.junit.Test;
import org.mockito.Mockito;
import org.traccar.Protocol;
import org.traccar.model.Position;
import org.traccar.Helper;

import static org.mockito.Mockito.*;

public class WatchProtocolDecoderTest {

    @Test
    public void getHasIndexTrueTest() {
        Protocol protocol = Mockito.mock(Protocol.class);
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(protocol);
        Assert.assertTrue(decoder.getHasIndex());
    }

    @Test
    public void getHasIndexFalseTest() {
        Protocol protocol = Mockito.mock(Protocol.class);
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(protocol);
        Assert.assertFalse(decoder.getHasIndex());
    }

    @Test
    public void getManufacturerTest() {
        Protocol protocol = Mockito.mock(Protocol.class);
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(protocol);
        Assert.assertEquals("testManufacturer", decoder.getManufacturer());
    }

    @Test
    public void decodeNullTest() throws Exception {
        protocol protocol = Mockito.mock(Protocol.class);
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(protocol);

        Assert.assertNull(decoder.decode(null, null, null));
    }

    @Test
    public void decodePositionTest() throws Exception {
        Protocol protocol = Mockito.mock(Protocol.class);
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(protocol);

        ByteBuf buf = Unpooled.copiedBuffer("this is a test message".getBytes());
        Position position = (Position) decoder.decode(null, null, buf);

        Assert.assertNotNull(position);
        Assert.assertEquals("this is a test message", position.getPayload());
    }

}
